// FUNCTION: BFME2 0x00067800 size=102 name=?loadRoadsAndBridges@BaseHeightMapRenderObjClass@@QAEXPAVW3DTerrainLogic@@_N@Z evidence=N:ledger tier=A
void BaseHeightMapRenderObjClass::loadRoadsAndBridges(W3DTerrainLogic *terrain, Bool saveGame)
{
	DX8DeviceLock lock;

	if (DXWrapper::_Get_D3D_Device8() && DXWrapper::_Get_D3D_Device8()->TestCooperativeLevel() != D3D_OK) {
		return;	// device not ready to render anything
	}

	if (m_roadBuffer) {
		m_roadBuffer->loadRoads();
	}
	if (m_bridgeBuffer) {
		m_bridgeBuffer->loadBridges(terrain, saveGame);
	}
}

