void TScorch::xfer(Xfer *xfer)
{
	if (xfer->IsLightCRC()) {
		return;
	}

	Xfer::Version version(1, 1);
	*xfer == version;
	*xfer == m_location.X;
	*xfer == m_location.Y;
	*xfer == m_location.Z;
	*xfer == m_radius;
	*xfer == m_scorchType;
	*xfer == m_flag;
}

