// FUNCTION: BFME2 0x00069168 size=165 name=?Compute_Intersection@PlaneClass@@QBE_NABVVector3@@0PAM@Z evidence=N:ledger tier=A
bool PlaneClass::Compute_Intersection(const Vector3 &p0, const Vector3 &p1, float *set_t) const
{
	float num, den;
	den = Vector3::Dot_Product(N, p1 - p0);

	// A zero denominator means the segment is parallel to the plane.
	if (den == 0.0f) {
		return false;
	}

	num = -(Vector3::Dot_Product(N, p0) - D);

	*set_t = num / den;

	// t outside 0..1: the line crosses the plane but the segment does not.
	if ((*set_t < 0.0f) || (*set_t > 1.0f)) {
		return false;
	}

	return true;
}

