// FUNCTION: BFME2 0x0006C6A3 size=63 name=?showAsVisibleCliff@BaseHeightMapRenderObjClass@@QBE_NHH@Z evidence=N:ledger tier=B hypothesis:cohesion
Bool BaseHeightMapRenderObjClass::showAsVisibleCliff(Int xIndex, Int yIndex) const
{
	Int xSize = m_map->getXExtent();
	if (xIndex < 0 || yIndex < 0 || yIndex >= m_map->getYExtent() || xIndex >= xSize) {
		return false;
	}
	return m_showAsVisibleCliff[xIndex + yIndex * xSize];
}

